import ignore from 'ignore';
import { toPosixPath } from './fs/toPosixPath.js';
/**
 * Default patterns that Mintlify always ignores, regardless of .mintignore configuration.
 * These directories are typically version control, IDE configs, or dependencies.
 */
export const DEFAULT_MINT_IGNORES = [
    '.git',
    '.github',
    '.claude',
    '.agents',
    '.idea',
    '.vscode',
    '.cursor',
    '.mintlify/**',
    '!.mintlify/**/',
    '!.mintlify/skills/**',
    '!.mintlify/**/*.json',
    '!.mintlify/**/*.yaml',
    '!.mintlify/**/*.yml',
    'node_modules',
    'README.md',
    'LICENSE.md',
    'CHANGELOG.md',
    'CONTRIBUTING.md',
];
/**
 * Processes the contents of a .mintignore file and returns an array of relevant patterns.
 * The ignore package automatically handles comments (lines starting with #) and empty lines.
 *
 * @param mintIgnoreContent The content of the .mintignore file.
 * @returns An array of glob patterns.
 */
export function processMintIgnoreString(mintIgnoreContent) {
    return mintIgnoreContent.split(/\r?\n/).map((line) => line.trim());
}
/**
 * Checks if a file path is ignored based on the provided glob patterns and default ignores.
 * Always includes DEFAULT_MINT_IGNORES in addition to any custom patterns provided.
 *
 * Compiles the patterns on every call, so this is for one-off checks only. To check
 * many paths, build a matcher once with {@link createMintIgnoreMatcher} and pass it
 * to {@link isMintIgnoredBy}.
 *
 * @param filePath The path of the file to check.
 * @param globs An array of custom glob patterns (output from processMintIgnoreString).
 * @param isDirectory Whether the path is a directory. Directory-only patterns such as `junk/`
 *   only match when this is true or `filePath` ends with a slash.
 * @returns True if the file matches any of the ignore patterns (default or custom), false otherwise.
 */
export function isMintIgnored(filePath, globs = [], isDirectory = false) {
    return isMintIgnoredBy(filePath, createMintIgnoreMatcher(globs), isDirectory);
}
/**
 * Checks a path against a matcher the caller already built.
 *
 * Prefer this over {@link isMintIgnored} in loops. Building the matcher is the
 * expensive half of the check, so hoisting it out of the loop with
 * {@link createMintIgnoreMatcher} makes that cost visible and pays it once.
 *
 * @param filePath The path of the file to check.
 * @param matcher A matcher from {@link createMintIgnoreMatcher}.
 * @param isDirectory Whether the path is a directory. Directory-only patterns such as `junk/`
 *   only match when this is true or `filePath` ends with a slash.
 * @returns True if the file matches any of the matcher's patterns, false otherwise.
 */
export function isMintIgnoredBy(filePath, matcher, isDirectory = false) {
    const { path: normalized, hadTrailingSlash } = normalizeMintIgnorePath(filePath);
    if (normalized.length === 0) {
        return false;
    }
    if (isDirectory || hadTrailingSlash) {
        return matcher.ignores(`${normalized}/`);
    }
    return matcher.ignores(normalized);
}
/**
 * Compiles the default ignores plus any custom patterns into a reusable matcher.
 *
 * Compiling is orders of magnitude more expensive than testing a single path
 * against the result, so anything checking more than a handful of paths should
 * build one matcher here and pass it to {@link isMintIgnoredBy} rather than
 * calling {@link isMintIgnored} per path.
 *
 * @param globs An array of custom glob patterns (output from processMintIgnoreString).
 * @returns A matcher covering DEFAULT_MINT_IGNORES plus the provided patterns.
 */
export function createMintIgnoreMatcher(globs = []) {
    return ignore().add(Array.from(new Set([...DEFAULT_MINT_IGNORES, ...globs])));
}
function normalizeMintIgnorePath(filePath) {
    let normalized = toPosixPath(filePath);
    const hadTrailingSlash = normalized.endsWith('/');
    while (normalized.startsWith('./')) {
        normalized = normalized.slice(2);
    }
    if (normalized.startsWith('/')) {
        normalized = normalized.slice(1);
    }
    normalized = normalized.replace(/\/+$/, '');
    return { path: normalized, hadTrailingSlash };
}
